def dihedral(cells, H, W):
    pts=set(map(tuple,cells))
    res=[]
    cur=pts
    for _ in range(4):
        rs={(-y,x) for y,x in cur}; cs={(y,-x) for y,x in cur}
        for s in (rs,cs):
            # normalize
            mr=min(y for y,_ in s); mc=min(x for _,x in s)
            res.append((sorted((y-mr,x-mc) for y,x in s)), '_fliph' if s==rs else '')
        cur={(x,-y) for y,x in cur}  # rotate
    return res

def analyze(inp, out):
    # find box: largest solid rectangle of 1s
    H=len(inp); W=len(inp[0])
    best=None
    for r in range(H):
        for c in range(W):
            if inp[r][c]==1:
                # extend
                r0=r; c0=c
                while r0+1<H and inp[r0+1][c]==1: r0+=1
                while c0+1<W and inp[r0][c0+1]==1: c0+=1
                h=r0-r+1; w=c0-c+1
                if best is None or h*w>best[0]: best=(h,w,r,c)
    h,w,r,c=best
    crop=[[inp[r+i][c+j] for j in range(w)] for i in range(h)]
    op=out
    return crop,op

